package com.householdfinance.finance.domain;import java.time.*;import java.util.*;public final class BillOccurrence{private final OccurrenceId id;private final BillId billId;private final LocalDate dueDate;private OccurrenceStatus status=OccurrenceStatus.PENDING;private TransactionId paidBy;private BillOccurrence(OccurrenceId i,BillId b,LocalDate d){id=i;billId=b;dueDate=d;}public static BillOccurrence create(BillId b,LocalDate d){return new BillOccurrence(OccurrenceId.newId(),b,d);}public static BillOccurrence rehydrate(UUID id,BillId bill,LocalDate dueDate,OccurrenceStatus status,TransactionId paidBy){var occurrence=new BillOccurrence(new OccurrenceId(id),bill,dueDate);occurrence.status=status;occurrence.paidBy=paidBy;return occurrence;}public void markPaid(TransactionId t){if(status==OccurrenceStatus.PAID)throw new DomainException("Bill occurrence already paid");status=OccurrenceStatus.PAID;paidBy=Objects.requireNonNull(t);}public OccurrenceId id(){return id;}public BillId billId(){return billId;}public LocalDate dueDate(){return dueDate;}public OccurrenceStatus status(){return status;}public TransactionId paidBy(){return paidBy;}}
